// src/components/Header.js
import React from 'react';
import { Link } from 'react-router-dom';

const Header = () => {
    return (
        <header>
            <nav>
                <ul>
                    <li><Link to="/">仪表盘</Link></li>
                    <li><Link to="/monitor">实时监控</Link></li>
                    <li><Link to="/history">历史数据</Link></li>
                    <li><Link to="/violate">违规车辆管理</Link></li>
                    <li><Link to="/username">用户名</Link></li>
                </ul>
            </nav>
        </header>
    );
};

export default Header;
